<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {storageApi,StorageApiError} from './api'
import type {Home,Item,Intent,Application,Event as StorageEvent} from './types'
import {useStorageText} from './text'
import {dateTime} from './format'
import StorageApplicationForm from './StorageApplicationForm.vue'
import StorageReceiveForm from './StorageReceiveForm.vue'
import StorageIntentPanel from './StorageIntentPanel.vue'
import StorageFollowupForm from './StorageFollowupForm.vue'
import WalletQrScanner from '../wallet/components/WalletQrScanner.vue'
import WalletCustomerLogin from '../wallet/components/WalletCustomerLogin.vue'
import '../wallet/wallet.css'
import './storage.css'
const props=defineProps<{customer:boolean}>(),route=useRoute(),router=useRouter(),{t,locale}=useStorageText(),store=computed(()=>String(route.params.storeId)),api=computed(()=>storageApi(store.value,!!props.customer))
const home=ref<Home|null>(null),error=ref(''),problems=ref<unknown[]>([]),loading=ref(false),busy=ref(false),login=ref(false),pending=ref(false),showForm=ref(false),showScan=ref(false),tab=ref('items'),filter=ref('all'),query=ref(''),receive=ref<Application|null>(null),reason=ref(''),selection=ref<Record<string,number>>({}),intent=ref<Intent|null>(null),code=ref(''),again=ref<{item:Item;intentId:string;quantity:number}|null>(null),storeInput=ref(''),correction=ref({itemId:'',reason:'',note:''})
const rule=ref({categoryId:'',name:'',months:3}),can=(p:string)=>home.value?.permissions.includes('wine_storage.'+p)??false
let generation=0
function fail(e:unknown){error.value=e instanceof Error?e.message:String(e);problems.value=e instanceof StorageApiError?e.problems:[];if(e instanceof StorageApiError&&e.status===401)login.value=true;pending.value=!!api.value.pending()}
async function load(){const g=generation;loading.value=true;try{const data=await api.value.get<Home>('/home');if(g!==generation)return;home.value=data;login.value=false;pending.value=!!api.value.pending();const hash=new URLSearchParams(route.hash.slice(1)).get('storage');if(hash&&/^WS\.[A-Za-z0-9_-]{43}$/.test(hash)){await router.replace({hash:''});await scan(hash)}}catch(e){if(g===generation)fail(e)}finally{if(g===generation)loading.value=false}}
async function run(work:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';problems.value=[];const g=generation;try{await work();if(g===generation)await load()}catch(e){if(g===generation)fail(e)}finally{if(g===generation)busy.value=false}}
const items=computed(()=>home.value?.items.filter(i=>(filter.value==='all'||i.status===filter.value)&&[i.snapshot.nameZh,i.snapshot.nameEn,i.snapshot.code,i.location,i.label,i.customerId].join(' ').toLowerCase().includes(query.value.toLowerCase()))??[])
function problemText(problem:unknown){const p=problem as {itemId?:string;code?:string};const item=home.value?.items.find(i=>i.id===p.itemId);return `${item?name(item):t('items')}: ${t(p.code==='EXPIRED'?'expired':'quantityChanged')}`}
function eventLines(e:StorageEvent){const d=e.details,lines:string[]=[];if(d.reason)lines.push(String(d.reason));if(d.note)lines.push(String(d.note));if(d.quantity)lines.push(`${t('quantity')}: ${d.quantity} · ${d.before} → ${d.after}`);if(Array.isArray(d.lines))for(const l of d.lines){const row=l as Record<string,unknown>;lines.push(`${row.nameZh||row.nameEn||t('items')} × ${row.quantity??''} ${row.note??''}`)}return lines}
function name(i:Item){return locale.value.startsWith('en')?i.snapshot.nameEn||i.snapshot.nameZh:i.snapshot.nameZh||i.snapshot.nameEn}
function choose(i:Item,checked:boolean){selection.value[i.id]=checked?1:0}
async function createIntent(){const selected=Object.entries(selection.value).filter(([,q])=>q>0).map(([itemId,quantity])=>({itemId,quantity}));const customers=new Set(selected.map(s=>home.value?.items.find(i=>i.id===s.itemId)?.customerId));if(!selected.length||customers.size!==1)throw new Error(t('noSelection'));intent.value=await api.value.command<Intent>('/intents',{customerId:props.customer?null:[...customers][0],selections:selected});tab.value='intents';selection.value={}}
async function scan(value:string){code.value=value;intent.value=await api.value.scan(value);showScan.value=false;tab.value='intents'}
function redeposit(value:{item:Item;intentId:string;quantity:number}){again.value=value;showForm.value=true;tab.value='applications'}
function saved(){showForm.value=false;again.value=null;receive.value=null;void load()}
function visibleIntent(i:Intent){return {...i,code:intent.value?.id===i.id?intent.value.code:null}}
watch(store,()=>{generation++;home.value=null;error.value='';login.value=false;busy.value=false;intent.value=null;code.value='';receive.value=null;selection.value={};showScan.value=false;showForm.value=false;again.value=null;storeInput.value=store.value;void load()},{immediate:true})
</script>
<template><main class="cards-page storage-page" :data-storage-role="customer?'customer':'merchant'"><header class="storage-page-header"><div class="storage-heading"><RouterLink :to="customer?`/wallet/${store}`:`/stores/${store}/wallet`">← {{t('back')}}</RouterLink><div><span class="cards-badge">{{t(customer?'customerArea':'merchantArea')}}</span><h1>{{t(customer?'title':'manage')}}</h1></div></div><button :disabled="busy||loading" @click="load">{{t('refresh')}}</button></header><section class="storage-panel storage-store"><p>{{t('storeId')}}: <strong>{{home?.storeName||t('loading')}}</strong></p><form v-if="home" class="storage-inline" @submit.prevent="router.push(customer?`/wallet/${encodeURIComponent(storeInput)}/wine-storage`:`/stores/${encodeURIComponent(storeInput)}/wine-storage`)"><select v-model="storeInput" :aria-label="t('storeId')"><option v-for="option in home.stores" :key="option.id" :value="option.id">{{option.name}}</option></select><button>{{t('switchStore')}}</button></form></section><p v-if="error" class="storage-error" role="alert">{{error}}</p><div v-if="problems.length" class="storage-error"><strong>{{t('problem')}}</strong><ul><li v-for="(problem,index) in problems" :key="index">{{problemText(problem)}}</li></ul></div><p v-if="loading" role="status">{{t('loading')}}</p><WalletCustomerLogin v-if="customer&&login" :store="store" @authenticated="load"/><button v-if="pending" :disabled="busy" @click="run(async()=>{const result=await api.recover();if(result&&typeof result==='object'&&'selections' in result)intent=result as Intent})">{{t('recover')}}</button>
<template v-if="home"><p v-if="!home.newBusinessEnabled" class="storage-notice">{{t('closed')}}</p><p class="storage-notice">{{t('expiryHint')}}</p><nav class="storage-tabs" :aria-label="t('sections')"><button v-for="v in ['items','applications','intents','history','rules']" :key="v" :class="{primary:tab===v}" :aria-pressed="tab===v" @click="tab=v">{{t(v)}}</button></nav><div class="storage-inline storage-actions"><button class="primary" v-if="customer&&home.newBusinessEnabled" :disabled="busy||pending" @click="again=null;showForm=!showForm;tab='applications'">{{t('apply')}}</button><button v-if="customer||can('deliver')" :disabled="busy||pending" @click="showScan=!showScan">{{t('scan')}}</button></div><WalletQrScanner v-if="showScan" purpose="storage" :title="t('scan')" :privacy-message="t('scanPrivacy')" :manual-label="t('pasteCode')" :invalid-message="t('invalidCode')" :disabled="busy||pending" @code="value=>run(()=>scan(value))"/>
<section v-if="tab==='items'" class="storage-panel storage-section"><h2>{{t('items')}}</h2><div class="storage-toolbar"><label>{{t('searchItems')}}<input v-model="query" :placeholder="t('searchItems')"></label><label>{{t('status')}}<select v-model="filter"><option v-for="s in ['all','stored','collected','expired']" :key="s" :value="s">{{t(s)}}</option></select></label><button class="primary" v-if="customer||can('deliver')" :disabled="busy||pending" @click="run(createIntent)">{{t(customer?'withdraw':'merchantIntent')}}</button></div><p v-if="!items.length" class="storage-empty">{{t('empty')}}</p><div class="storage-grid"><article v-for="i in items" :key="i.id" class="storage-panel"><div class="storage-photos"><img v-if="i.snapshot.receiptPhotos[0]" :src="`${api.base}/photos/${i.snapshot.receiptPhotos[0]}`" :alt="name(i)"></div><h2>{{name(i)}}</h2><small>{{i.snapshot.code}} · {{t(i.status)}}</small><p>{{t('remaining')}} {{i.remaining}} / {{i.quantity}} {{t('quantity')}} · {{t(i.opened?'opened':'whole')}} · {{t(i.source)}}</p><small v-if="!customer">{{t('customerId')}} {{i.customerId}}</small><p>{{t('receivedAt')}} {{dateTime(i.receivedAt,i.snapshot.timezone)}}</p><p><strong>{{t('expiresAt')}} {{dateTime(i.expiresAt,i.snapshot.timezone)}} ({{i.snapshot.timezone}})</strong></p><p>{{i.snapshot.rule.name}} · {{i.snapshot.rule.months}} {{t('months')}} · v{{i.snapshot.rule.version}}</p><p>{{i.snapshot.note}}</p><p v-if="!customer">{{t('location')}} {{i.location}} · {{t('label')}} {{i.label}}</p><details><summary>{{t('photoPhase')}}</summary><div class="storage-photos"><img v-for="id in [...i.snapshot.applicationPhotos,...i.snapshot.receiptPhotos]" :key="id" :src="`${api.base}/photos/${id}`" :alt="t('photos')"></div></details><div v-if="i.status==='stored'&&(customer||can('deliver'))" class="storage-inline"><label><input type="checkbox" :checked="!!selection[i.id]" @change="choose(i,($event.target as HTMLInputElement).checked)">{{t('select')}}</label><input v-if="selection[i.id]" v-model.number="selection[i.id]" type="number" min="1" :max="i.opened?1:i.remaining"></div><button v-if="!customer&&can('correct')" @click="correction={itemId:i.id,reason:'',note:''}">{{t('correction')}}</button><StorageFollowupForm v-if="!customer&&can('receive')" :api="api" :item="i" :disabled="busy||pending" @saved="load" @error="fail"/></article></div><form v-if="correction.itemId" class="storage-panel" @submit.prevent="run(async()=>{await api.command(`/items/${correction.itemId}/corrections`,correction);correction.itemId=''})"><p>{{t('correctHint')}}</p><label>{{t('reason')}}<input v-model="correction.reason" required></label><label>{{t('note')}}<textarea v-model="correction.note" required/></label><button :disabled="busy||pending">{{t('confirm')}}</button></form></section>
<section v-if="tab==='applications'" class="storage-panel storage-section"><h2>{{t('applications')}}</h2><details><summary>{{t('rules')}}</summary><p v-for="r in home.rules" :key="r.id">{{r.name}} · {{r.months}} {{t('months')}} · v{{r.version}}</p></details><StorageApplicationForm v-if="showForm&&customer&&home.newBusinessEnabled" :key="again?.intentId??'new'" :api="api" :disabled="busy||pending" :again="again" @saved="saved" @error="fail"/><StorageReceiveForm v-if="receive" :key="receive.id" :application="receive" :home="home" :api="api" :disabled="busy||pending||!home.newBusinessEnabled" @saved="saved" @error="fail"/><p v-if="!home.applications.length">{{t('empty')}}</p><article v-for="a in home.applications" :key="a.id" class="storage-panel"><strong>{{t(a.status)}}</strong><small>{{a.id}} · {{dateTime(a.createdAt,home.timezone)}}</small><p v-if="!customer">{{t('customerId')}} {{a.customerId}}</p><h3>{{t('original')}}</h3><div v-for="l in a.lines" :key="l.id"><p>{{l.nameZh||l.nameEn}} · {{l.nameEn}} × {{l.quantity}} · {{t(l.opened?'opened':'whole')}} · {{t(l.source)}}</p><p>{{l.note}}</p><div class="storage-photos"><img v-for="photo in l.photos" :key="photo" :src="`${api.base}/photos/${photo}`" :alt="t('photos')"></div></div><div v-if="a.confirmation"><h3>{{t('confirmed')}}</h3><p>{{a.confirmation.reason}}</p><p v-for="l in a.confirmation.lines" :key="l.lineId">{{l.nameZh||l.nameEn||home.items.find(i=>i.applicationId===a.id)?.snapshot.nameZh}} × {{l.quantity}} · {{t(l.opened?'opened':'whole')}} · {{t(l.source)}} · {{l.note}}</p></div><p>{{a.reason}}</p><template v-if="a.status==='pending'"><button v-if="customer" :disabled="busy||pending" @click="run(()=>api.command(`/applications/${a.id}/cancel`,{}))">{{t('cancel')}}</button><template v-else-if="can('receive')"><button :disabled="busy||pending||!home.newBusinessEnabled" @click="receive=a">{{t('receive')}}</button><input v-model="reason" :placeholder="t('reason')"><button :disabled="busy||pending||!reason.trim()" @click="run(()=>api.command(`/applications/${a.id}/reject`,{reason}))">{{t('reject')}}</button></template></template></article></section>
<section v-if="tab==='intents'" class="storage-section"><h2>{{t('intents')}}</h2><p v-if="!intent&&!home.intents.length" class="storage-panel storage-empty">{{t('empty')}}</p><StorageIntentPanel v-if="intent&&!home.intents.some(i=>i.id===intent?.id)" :intent="intent" :items="home.items" :customer="!!customer" :timezone="home.timezone" :disabled="busy||pending" :can-deliver="can('deliver')"/><StorageIntentPanel v-for="i in home.intents" :key="i.id" :intent="visibleIntent(i)" :items="home.items" :customer="!!customer" :timezone="home.timezone" :disabled="busy||pending" :can-deliver="can('deliver')" :authorization-code="intent?.id===i.id?code:''" @authorize="run(()=>api.command(`/intents/${i.id}/authorize`,{code}))" @deliver="run(async()=>{await api.command(`/intents/${i.id}/deliver`,{});intent=null})" @cancel="run(async()=>{await api.command(`/intents/${i.id}/cancel`,{});intent=null})" @again="redeposit"/></section>
<section v-if="tab==='history'" class="storage-panel storage-section"><h2>{{t('history')}}</h2><p v-if="!home.events.length">{{t('empty')}}</p><article v-for="e in home.events" :key="e.id" class="storage-panel"><strong>{{t(e.action)}}</strong><p>{{dateTime(e.createdAt,home.timezone)}} · {{t('author')}} {{e.actorId}}</p><small>{{e.sourceId}}</small><details><summary>{{t('showDetail')}}</summary><p v-for="(line,index) in eventLines(e)" :key="index">{{line}}</p><div v-if="e.action==='photos.added'" class="storage-photos"><img v-for="photo in (e.details.photos as string[])" :key="photo" :src="`${api.base}/photos/${photo}`" :alt="t('photos')"></div></details></article></section>
<section v-if="tab==='rules'" class="storage-panel storage-section"><h2>{{t('rules')}}</h2><p>{{t('ruleHint')}}</p><p v-for="r in home.rules" :key="r.id">{{r.name}} · {{r.months}} {{t('months')}} · v{{r.version}}</p><form v-if="!customer&&can('rules.manage')" @submit.prevent="run(()=>api.command('/rules',rule))"><label>{{t('category')}}<select v-model="rule.categoryId" required><option v-for="c in home.categories" :key="c.id" :value="c.id">{{c.nameZh||c.nameEn}}</option></select></label><label>{{t('ruleName')}}<input v-model="rule.name" required maxlength="200"></label><label>{{t('months')}}<input v-model.number="rule.months" type="number" min="1" max="120" required></label><button :disabled="busy||pending||!home.newBusinessEnabled">{{t('save')}}</button></form></section>
</template></main></template>
